INSERT INTO "Equipment" ("slug", "reference", "manufacturer", "model", "partNumber", "sector", "category", "description", "conditionKey", "conditionNote", "quantity", "location", "lastVerifiedAt", "priceType", "price", "currency", "includesShipping", "testSummary", "specs", "image", "imageCaption", "isPublished", "isSample", "searchKey", "createdAt", "updatedAt")
VALUES ('disco-dfd6361-dicing-saw', 'ZX-QWXZ1S', 'DISCO', 'DFD6361', 'DFD6361-FS', 'SEMICONDUCTOR', 'Dicing & grinding', 'Fully automatic dicing saw for 6/8-inch wafers, two-chuck table configuration for continuous cut/load overlap. Removed from a production line during a tool consolidation and stored in a controlled warehouse. Full alignment and cut-quality report available to qualified buyers.', 'USED_TESTED', 'Condition per the owner''s maintenance report, shared with us Oct 2026.', 1, 'Hillsboro, OR, USA', '2026-11-05T17:00:00.000+00:00', 'QUOTE', NULL, NULL, 0, 'Powered on at the owner''s site; spindle run and chuck motion verified by their maintenance team. Cut-quality test can be arranged before purchase.', '[{"label":"Wafer size","value":"6 in / 8 in"},{"label":"Spindle","value":"Air-bearing spindle, up to 60,000 rpm"},{"label":"Chuck tables","value":"2 (cut / load overlap)"},{"label":"Blade","value":"2-inch dicing blade"},{"label":"Control","value":"DISCO factory control, English UI"},{"label":"Power","value":"200 V 3-phase 50/60 Hz"}]', '/images/sample-dicing.jpg', 'Representative photo of this tool type — not the actual asset.', 1, 1, 'discodfd6361dfd6361fsdicinggrinding', '2026-11-12T20:00:52.311+00:00', '2026-11-12T20:00:52.311+00:00');

