VALUES ('accretech-uf3000-wafer-prober', 'ZX-G9SW23', 'Accretech', 'UF3000', NULL, 'SEMICONDUCTOR', 'Wafer test & probing', '300 mm fully automatic wafer prober with thermal chuck. Deinstalled by the original owner with cleanroom-standard procedures. Compatible with common ATE platforms; integration details and test history available on request.', 'USED_TESTED', 'Condition per the owner''s deinstall checklist, Oct 2026.', 1, 'Austin, TX, USA', '2026-10-28T14:00:00.000+00:00', 'QUOTE', NULL, NULL, 0, 'System self-test passed at deinstallation; prober card interface inspected. Thermal chuck performance verified to spec.', '[{"label":"Wafer size","value":"300 mm"},{"label":"Chuck","value":"Thermal chuck, -10 to 150 °C"},{"label":"Alignment","value":"Automatic, off-axis microscope"},{"label":"ATE interface","value":"Advantest / Teradyne interfaces available"},{"label":"Footprint","value":"Glovebox-compatible, cleanroom ready"}]', '/images/sample-prober.jpg', 'Representative photo of this tool type — not the actual asset.', 1, 1, 'accretechuf3000wafertestprobing', '2026-11-12T20:00:52.313+00:00', '2026-11-12T20:00:52.313+00:00');

