VALUES ('besi-datacon-2200-evo-die-bonder', 'ZX-F8NWAZ', 'Besi', 'Datacon 2200 EVO', NULL, 'SEMICONDUCTOR', 'Assembly & packaging', 'High-accuracy die bonder for advanced packaging applications, removed from an R&D line. Stored in ESD-safe packaging since removal. Sold as a complete system with standard feeders; options list available on request.', 'USED_UNTESTED', 'Owner reports the tool was operational at removal; not powered on since.', 1, 'Chandler, AZ, USA', '2026-10-20T16:00:00.000+00:00', 'QUOTE', NULL, NULL, 0, NULL, '[{"label":"Placement accuracy","value":"±3.5 µm at 3σ"},{"label":"Die size range","value":"0.25 × 0.25 mm to 50 × 50 mm"},{"label":"Bond heads","value":"Configurable, 2 installed"},{"label":"Substrates","value":"Strip and wafer handling"},{"label":"Utilities","value":"CDA, vacuum, 200–240 V"}]', '/images/sample-diebonder.jpg', 'Representative photo of this tool type — not the actual asset.', 1, 1, 'besidatacon2200evoassemblypackaging', '2026-11-12T20:00:52.314+00:00', '2026-11-12T20:00:52.314+00:00');

INSERT INTO "Equipment" ("slug", "reference", "manufacturer", "model", "partNumber", "sector", "category", "description", "conditionKey", "conditionNote", "quantity", "location", "lastVerifiedAt", "priceType", "price", "currency", "includesShipping", "testSummary", "specs", "image", "imageCaption", "isPublished", "isSample", "searchKey", "createdAt", "updatedAt")
VALUES ('dell-poweredge-r740xd-12-units', 'ZX-BZM41W', 'Dell', 'PowerEdge R740xd', 'R740XD-2U-24D', 'DATACENTER', 'Rack servers', 'Twelve identical R740xd nodes pulled from a single cluster decommission. Consistent configuration across all units; drives removed and destroyed by the owner. Per-unit testing completed before palletizing.', 'USED_TESTED', 'Tested by the equipment owner; results shared with us Nov 2026.', 12, 'Quincy, WA, USA', '2026-11-02T17:00:00.000+00:00', 'UNIT', '4850', 'USD', 0, 'Each unit powered on, POST verified, iDRAC9 reachable and firmware inventoried. Memory and CPU verified against the config list. Drives not included.', '[{"label":"CPU","value":"2 × Intel Xeon Gold 6248R (24C, 3.0 GHz)"},{"label":"Memory","value":"384 GB DDR4-2933 (12 × 32 GB)"},{"label":"Drive bays","value":"24 × 2.5-in SFF (drives removed)"},{"label":"Power","value":"2 × 1100 W Titanium PSU"},{"label":"Management","value":"iDRAC9 Enterprise"},{"label":"Rails","value":"Included, ready-to-rack"}]', '/images/sample-server.jpg', 'Representative photo — the lot is packed and palletized at the owner''s site.', 1, 1, 'dellpoweredger740xdr740xd2u24drackservers', '2026-11-12T20:00:52.315+00:00', '2026-11-12T20:00:52.315+00:00');

