VALUES ('haas-vf-2ss-2018', 'ZX-8VMF6H', 'Haas', 'VF-2SS', NULL, 'INDUSTRIAL', 'CNC machining centers', '2018 VF-2SS vertical machining center with side-mount tool changer and high-speed spindle. Under power and inspectable under load in the owner''s shop. Full service history from a single-owner facility.', 'USED_TESTED', 'Run-off test witnessed by our team, Oct 2026.', 1, 'Portland, OR, USA', '2026-11-07T17:00:00.000+00:00', 'QUOTE', NULL, NULL, 0, 'Run-off under power: spindle run-out and axis backlash within Haas spec, tool changer cycled 50×, way covers and coolant system inspected. Service log available.', '[{"label":"Travels X/Y/Z","value":"30 × 16 × 20 in"},{"label":"Spindle","value":"12,000 rpm, CT40, direct drive"},{"label":"Tool changer","value":"24+1 side-mount"},{"label":"Table","value":"36 × 14 in, 1,200 lb capacity"},{"label":"Control","value":"Haas NGC, 4th-axis ready"},{"label":"Year","value":"2018"}]', '/images/sample-vmc.jpg', 'Representative photo — not the actual machine.', 1, 1, 'haasvf2sscncmachiningcenters', '2026-11-12T20:00:52.318+00:00', '2026-11-12T20:00:52.318+00:00');

