VALUES ('mazak-qt-250-2015', 'ZX-1FBW0X', 'Mazak', 'QT-250', NULL, 'INDUSTRIAL', 'CNC lathes', '2015 Mazak QT-250 turning center sold as-is from a facility closure. Spindle rotates under power; the machine has not been inspected or run off. Inspections can be arranged on site before an offer is accepted.', 'AS_IS', 'Sold as-is, where-is; no inspection performed yet.', 1, 'Sacramento, CA, USA', '2026-10-15T16:00:00.000+00:00', 'QUOTE', NULL, NULL, 0, 'Power-on only: spindle and turret rotate. No accuracy or run-off test performed.', '[{"label":"Swing","value":"20.8 in over bed"},{"label":"Max turning length","value":"27.6 in"},{"label":"Spindle bore","value":"3.5 in"},{"label":"Turret","value":"12-station"},{"label":"Control","value":"Mazatrol Smooth"},{"label":"Year","value":"2015"}]', '/images/sample-lathe.jpg', 'Representative photo — not the actual machine.', 1, 1, 'mazakqt250cnclathes', '2026-11-12T20:00:52.319+00:00', '2026-11-12T20:00:52.319+00:00');

