VALUES ('york-yvaa200-air-cooled-chiller', 'ZX-J6SW9M', 'York (JCI)', 'YVAA200', NULL, 'INDUSTRIAL', 'Cooling & plant support', '200-ton air-cooled screw chiller, 2019, in service until September 2026. Refrigerant circuit pressure-tested at decommission; run-under-load witnessed by the owner''s contractor. Rigging and freight quotes available on request.', 'USED_TESTED', 'Run-under-load witnessed by the owner''s mechanical contractor, Sep 2026.', 1, 'Boise, ID, USA', '2026-10-30T15:00:00.000+00:00', 'QUOTE', NULL, NULL, 0, 'Run under load for 2 hours at decommission: oil pressure, suction and discharge pressures within York operating envelope. Service records available.', '[{"label":"Capacity","value":"200 tons nominal"},{"label":"Compressor","value":"2 × screw compressors, R-134a"},{"label":"Leaving water temp","value":"Down to 40 °F"},{"label":"Voltage","value":"460 V 3-phase 60 Hz"},{"label":"Year","value":"2019"}]', '/images/sample-chiller.jpg', 'Representative photo — not the actual unit.', 1, 1, 'yorkjciyvaa200coolingplantsupport', '2026-11-12T20:00:52.321+00:00', '2026-11-12T20:00:52.321+00:00');
